function pendingApprovalCounts(){const doneIds=new Set(getAdminApprovalRecords().map(r=>r.id)),fixed=approvals.map((a,i)=>({type:a[0],id:`DEMO-${i}`})).filter(x=>!doneIds.has(x.id)),shared=getSharedApprovals();const count=(fixedType,sharedType)=>fixed.filter(x=>x.type===fixedType).length+shared.filter(x=>x.subtype===sharedType).length;return {leave:count('leave','leave'),overtime:count('overtime','overtime'),correction:count('correction','correction'),total:fixed.length+shared.length}}
