function getPayrollAdjustments(){try{return JSON.parse(localStorage.getItem('bombhr-payroll-adjustments-v123')||'{}')}catch(e){return {}}}
function payrollProfileForRoster(e){const p=employeeSalaryProfile(e.id);return {...p,overtime:p.overtime||e.overtime,healthInsurance:p.healthInsurance||e.deduction}}
function payrollEmployeeTotal(e){const p=payrollProfileForRoster(e),custom=getPayrollAdjustments()[e.id]||[];return p.base+p.positionAllowance+p.attendanceBonus+p.seniorityAllowance+p.laborPensionIncome+p.overtime-p.healthInsurance-p.laborInsurance-p.lateDeduction+custom.reduce((n,x)=>n+(['收入','加給'].includes(x.type)?1:-1)*Number(x.amount||0),0)}
function payrollEmployeeRows(){const adjustments=getPayrollAdjustments();return payrollRoster.map(e=>{const p=payrollProfileForRoster(e),custom=adjustments[e.id]||[];return `<tr data-search-row><td><div class="person"><span class="avatar">${e.name[0]}</span><div><b>${e.name}</b><small>${e.id}</small></div></div></td><td><b>${e.department}</b><small class="table-subline">${e.position}</small></td><td>NT$ ${(p.base+p.positionAllowance+p.attendanceBonus+p.seniorityAllowance+p.laborPensionIncome).toLocaleString()}</td><td>NT$ ${p.overtime.toLocaleString()}</td><td class="number-negative">- NT$ ${(p.healthInsurance+p.laborInsurance+p.lateDeduction).toLocaleString()}</td><td>${custom.length?`${custom.length} 項・${custom.map(x=>x.name).join('、')}`:'—'}</td><td><strong class="net-pay">NT$ ${payrollEmployeeTotal(e).toLocaleString()}</strong></td><td>${badge(e.status)}</td><td class="row-actions"><button class="table-primary-btn" data-payroll-adjust="${e.id}">新增項目</button><button data-payroll-person-detail="${e.id}">查看</button></td></tr>`}).join('')}
function payrollView(){const total=payrollRoster.reduce((n,e)=>n+payrollEmployeeTotal(e),0);return head('人員薪資管理','Payroll','固定薪資直接連動員工人事資料卡；本頁只處理每月核對、人工項目、薪資條與關帳',`<button class="secondary-btn strong-action" data-bank-master>企業銀行</button><button class="secondary-btn strong-action" data-payroll-print>薪資條列印</button><button class="secondary-btn strong-action" data-payroll-export>匯出薪資</button><button class="primary-btn" data-payroll-lock>關帳本期薪資</button>`)+`<div class="payroll-source-banner"><div><i>✓</i><span><b>薪資來源：員工人事資料卡</b><small>底薪、職務津貼、投保資料與銀行帳號皆由人事建檔自動帶入；永久調薪請回人事資料修改並設定生效日。</small></span></div><button data-route-go="employees">前往員工人事 →</button></div><div class="stat-grid">${stat('本月薪資人數',String(payrollRoster.length),'自動同步在職員工')}${stat('本月薪資總額',`NT$ ${total.toLocaleString()}`,'包含人工新增項目')}${stat('待核對人員',String(payrollRoster.filter(x=>x.status==='待核對').length),'點擊員工查看明細','trend warn')}${stat('薪資月份','2026 年 7 月','預計 2026/08/05 發放')}</div>`+panel('2026 年 7 月員工薪資','人事資料同步＋每月出勤與簽核結果',toolbar('搜尋姓名、員編、部門或職位',`<select class="filter-select"><option>全部部門</option><option>營運－企劃部</option><option>營運－技術部</option><option>財務人事行政</option></select><select class="filter-select"><option>全部狀態</option><option>待核對</option><option>已確認</option></select>`)+`<div class="table-wrap"><table class="payroll-roster-table"><thead><tr><th>員工</th><th>部門／職位</th><th>固定薪資</th><th>加班費</th><th>勞健保扣款</th><th>人工項目</th><th>實領金額</th><th>狀態</th><th>操作</th></tr></thead><tbody>${payrollEmployeeRows()}</tbody></table></div>`)}
function payrollAdjustmentModal(employeeId){const e=payrollRoster.find(x=>x.id===employeeId);if(!e)return;openModal('新增當月薪資項目',`${e.name}・${e.id}・僅影響 2026 年 7 月薪資`,`<div class="form-grid"><label class="form-field">項目名稱<input id="adjustmentName" class="form-control" placeholder="例如：績效獎金、交通津貼、借支扣款"></label><label class="form-field">類型<select id="adjustmentType" class="form-control"><option>收入</option><option>扣款</option></select></label><label class="form-field">金額<input id="adjustmentAmount" type="number" min="1" class="form-control" placeholder="請輸入正整數"></label><label class="form-field">使用方式<select id="adjustmentUsage" class="form-control"><option>僅本月使用</option><option>建立為常用項目</option></select></label><label class="form-field full">備註<input id="adjustmentNote" class="form-control" placeholder="說明新增原因"></label></div><p id="adjustmentError" class="form-error"></p>`,`<button class="secondary-btn" data-modal-close>取消</button><button class="primary-btn" id="saveAdjustment">新增項目</button>`);$('#saveAdjustment').onclick=()=>{const name=$('#adjustmentName').value.trim(),amount=Number($('#adjustmentAmount').value||0);if(!name||amount<=0){$('#adjustmentError').textContent='請填寫項目名稱與正確金額。';return}const all=getPayrollAdjustments();(all[e.id]||(all[e.id]=[])).push({name,type:$('#adjustmentType').value,amount,note:$('#adjustmentNote').value.trim(),usage:$('#adjustmentUsage').value,operator:currentProfile().name,time:new Date().toLocaleString('zh-TW',{hour12:false})});localStorage.setItem('bombhr-payroll-adjustments-v123',JSON.stringify(all));closeModal();window.dispatchEvent(new HashChangeEvent('hashchange'));toast(`${name}已加入 ${e.name} 的本月薪資`)}}
function payrollPersonDetailModal(employeeId){const e=payrollRoster.find(x=>x.id===employeeId),p=e?payrollProfileForRoster(e):null,custom=getPayrollAdjustments()[employeeId]||[];if(!e)return;const deductions=p.healthInsurance+p.laborInsurance+p.lateDeduction;openModal('員工薪資明細',`${e.name}・${e.id}・${e.department}／${e.position}`,`<div class="salary-detail-grid"><div><small>人事固定薪資</small><b>NT$ ${(p.base+p.positionAllowance+p.attendanceBonus+p.seniorityAllowance+p.laborPensionIncome).toLocaleString()}</b></div><div><small>本月加班費</small><b>NT$ ${p.overtime.toLocaleString()}</b></div><div><small>本月扣款</small><b class="number-negative">- NT$ ${deductions.toLocaleString()}</b></div><div><small>本月實領</small><strong>NT$ ${payrollEmployeeTotal(e).toLocaleString()}</strong></div></div><div class="table-wrap"><table><thead><tr><th>項目</th><th>類型／來源</th><th>金額</th><th>備註</th></tr></thead><tbody>${[['底薪',p.base],['職務津貼',p.positionAllowance],['全勤獎金',p.attendanceBonus],['年資津貼',p.seniorityAllowance],['勞退（原表收入欄）',p.laborPensionIncome],['加班費',p.overtime]].map(x=>`<tr><td>${x[0]}</td><td>${x[0]==='加班費'?'出勤與加班簽核':'人事資料卡'}</td><td>NT$ ${x[1].toLocaleString()}</td><td>${x[0]==='加班費'?'系統計算':'專員薪資架構'}</td></tr>`).join('')}<tr><td>勞健保及其他扣款</td><td>投保與出勤資料</td><td class="number-negative">- NT$ ${deductions.toLocaleString()}</td><td>扣款以負號表示</td></tr>${custom.map(x=>`<tr><td>${x.name}</td><td>人工${x.type}</td><td class="${x.type==='扣款'?'number-negative':''}">${x.type==='扣款'?'- ':''}NT$ ${Number(x.amount).toLocaleString()}</td><td>${x.note||'—'}<small class="table-subline">${x.operator}・${x.time}</small></td></tr>`).join('')}</tbody></table></div>`,`<button class="secondary-btn" data-modal-close>關閉</button><button class="primary-btn" data-payroll-adjust="${e.id}">＋ 新增人工項目</button>`);$$('[data-payroll-adjust]').forEach(b=>b.onclick=()=>payrollAdjustmentModal(b.dataset.payrollAdjust))}
function payrollSlipItems(e){const p=payrollProfileForRoster(e),custom=getPayrollAdjustments()[e.id]||[];return [{name:'底薪',amount:p.base},{name:'職務津貼',amount:p.positionAllowance},{name:'全勤獎金',amount:p.attendanceBonus},{name:'年資津貼',amount:p.seniorityAllowance},{name:'加班費',amount:p.overtime},{name:'勞退',amount:p.laborPensionIncome},{name:'健保扣款',amount:-p.healthInsurance},{name:'勞保扣款',amount:-p.laborInsurance},{name:'遲到扣款',amount:-p.lateDeduction},...custom.map(x=>({name:x.name,amount:(['收入','加給'].includes(x.type)?1:-1)*Number(x.amount)}))].filter(x=>x.amount!==0)}
function payrollSlip(e){return `<section class="payroll-slip"><div class="slip-brand"><b>ABOMB</b><span>2026 年 7 月薪資明細</span></div><div class="slip-employee"><b>${e.name}　${e.id}</b><span>${e.department}</span></div><div class="slip-items">${payrollSlipItems(e).map(x=>`<div><small>${x.name}</small><b class="${x.amount<0?'negative':''}">${x.amount<0?'-':''}${Math.abs(x.amount).toLocaleString()}</b></div>`).join('')}</div><div class="slip-net"><small>實領金額</small><strong>${payrollEmployeeTotal(e).toLocaleString()}</strong></div></section>`}
function payrollPrintModal(){const pages=[];for(let i=0;i<payrollRoster.length;i+=7)pages.push(`<div class="payroll-print-page">${payrollRoster.slice(i,i+7).map((e,j)=>`${j?'<div class="cut-line">✂　裁切線</div>':''}${payrollSlip(e)}`).join('')}</div>`);openModal('橫式薪資條列印','A4 橫式・每頁最多 7 位・重點文字放大・純黑白',`<div class="print-control-note">目前共 ${payrollRoster.length} 位員工、${pages.length} 頁。格子高度已降低，但項目名稱與金額放大；收入顯示一般金額，只有扣款顯示負號。</div><div id="payrollPrintArea">${pages.join('')}</div>`,`<button class="secondary-btn" data-modal-close>關閉</button><button class="primary-btn" id="printPayrollSlips">列印薪資條</button>`);document.body.classList.add('payroll-print-open');$('#printPayrollSlips').onclick=()=>{addAudit('列印薪資條',`${payrollRoster.length} 位員工・2026 年 7 月`);window.print()};$$('[data-modal-close]').forEach(b=>b.onclick=()=>{document.body.classList.remove('payroll-print-open');closeModal()})}
function departmentPayrollModal(id){const d=payrollDepartments.find(x=>x.id===id);if(!d)return;openModal(d.name,`${d.count} 位員工・主管 ${d.manager}・2026 年 7 月薪資核對`,`<div class="department-modal-summary"><div><small>部門薪資總額</small><b>NT$ ${d.total.toLocaleString()}</b></div><div><small>待核對</small><b>${d.pending} 人</b></div><div><small>異常</small><b>${d.exception} 人</b></div></div><div class="table-wrap"><table><thead><tr><th>員工</th><th>職位／薪資範本</th><th>固定薪資</th><th>變動項目</th><th>應發</th><th>實領</th><th>狀態</th><th>操作</th></tr></thead><tbody>${d.employees.map((e,i)=>`<tr><td><div class="person"><span class="avatar">${e[0][0]}</span><div><b>${e[0]}</b><small>${e[1]}</small></div></div></td><td>${e[2]}</td><td>NT$ ${e[3].toLocaleString()}</td><td class="number-positive">+ NT$ ${e[4].toLocaleString()}</td><td><b>NT$ ${e[5].toLocaleString()}</b></td><td><b>NT$ ${e[6].toLocaleString()}</b></td><td>${badge(e[7])}</td><td><button class="table-primary-btn" data-payroll-person="${id}:${i}">完整明細</button></td></tr>`).join('')}</tbody></table></div>`,`<button class="secondary-btn" data-modal-close>關閉</button>`);$$('[data-payroll-person]').forEach(b=>b.onclick=()=>employeePayrollModal(...b.dataset.payrollPerson.split(':')))}
function employeePayrollModal(deptId,index){const d=payrollDepartments.find(x=>x.id===deptId),e=d?.employees[+index];if(!e)return;openModal('個人薪資完整明細',`${e[0]}・${e[1]}・${d.name}`,`<div class="employee-profile-banner"><span class="avatar">${e[0][0]}</span><div><b>${e[0]}</b><small>${e[2]}・套用「${e[2]}」職位薪資範本</small></div>${badge(e[7])}</div><div class="salary-detail-grid"><div><small>固定薪資</small><b>NT$ ${e[3].toLocaleString()}</b></div><div><small>變動項目</small><b class="number-positive">+ NT$ ${e[4].toLocaleString()}</b></div><div><small>應發薪資</small><strong>NT$ ${e[5].toLocaleString()}</strong></div><div><small>扣款後實領</small><strong>NT$ ${e[6].toLocaleString()}</strong></div></div><div class="payroll-note">此員工套用職位薪資範本；若有個人加給或調薪，將另存個人調整並保留生效日、操作人與異動原因。</div><div class="table-wrap"><table><thead><tr><th>薪資項目</th><th>來源</th><th>金額</th></tr></thead><tbody><tr><td>底薪與職務津貼</td><td>職位薪資範本</td><td>NT$ ${e[3].toLocaleString()}</td></tr><tr><td>加班／績效／其他收入</td><td>出勤、簽核與人工調整</td><td class="number-positive">+ NT$ ${e[4].toLocaleString()}</td></tr><tr><td>勞健保及其他扣款</td><td>投保與扣款規則</td><td class="number-negative">- NT$ ${(e[5]-e[6]).toLocaleString()}</td></tr></tbody></table></div>`,`<button class="secondary-btn" data-modal-close>關閉</button><button class="primary-btn" data-payroll-manual>新增個人調整</button>`);$$('[data-payroll-manual]').forEach(b=>b.onclick=payrollManualModal)}
const defaultPermissionGroups=[
 {name:'經營管理',members:'3',features:'全部功能・全部查看與編輯',scope:'ABOMB 台中總公司',protected:true},
 {name:'部門主管',members:'12',features:'人事／出勤／排班／簽核；薪資唯讀',scope:'所屬部門',protected:false},
 {name:'財務人事行政',members:'6',features:'人事／出勤／排班／假別／簽核／薪資架構／福利／報表',scope:'ABOMB 台中總公司',protected:false},
 {name:'系統管理',members:'2',features:'帳號／角色／功能權限／資料權限／系統設定；薪資不可見',scope:'ABOMB 台中總公司',protected:false}
];
function getPermissionGroups(){try{return JSON.parse(localStorage.getItem('bombhr-permission-groups-v121')||'null')||defaultPermissionGroups}catch(e){return defaultPermissionGroups}}
function permissionsView(){const role=currentRole(),rows=getPermissionGroups();return head('角色與權限群組','Roles & Permissions','預設範本可調整，企業亦可自訂群組名稱、功能權限與資料範圍',`<button class="primary-btn" data-add="role">＋ 新增權限群組</button>`)+panel('權限群組','角色名稱不寫死；「經營管理」為受保護的最高權限範本',`<div class="permission-banner">安全規則：財務人事行政不可修改自己的最高權限，也不可建立、刪除或降級經營管理角色。</div><div class="table-wrap"><table><thead><tr><th>群組名稱</th><th>成員</th><th>功能範圍</th><th>資料範圍</th><th>狀態</th><th>操作</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td><b>${x.name}</b>${x.protected?' <small>受保護</small>':''}</td><td>${x.members}</td><td>${x.features}</td><td>${x.scope}</td><td>${badge('啟用')}</td><td class="row-actions"><button data-role-edit="${i}" ${(role==='hradmin'&&(x.protected||x.name==='財務人事行政'))?'disabled title="不得修改最高權限或自身權限"':''}>編輯權限</button>${!x.protected?`<button data-role-delete="${i}" ${role==='hradmin'?'disabled title="此群組無刪除角色權限"':''}>刪除</button>`:''}</td></tr>`).join('')}</tbody></table></div>`)}
function getAuditLog(){try{return JSON.parse(localStorage.getItem('bombhr-sensitive-audit-v121')||'[]')}catch(e){return []}}
function addAudit(action,target='2026 年 7 月薪資'){const p=currentProfile(),rows=getAuditLog();rows.unshift({action,target,operator:p.name,operatorId:p.id,role:p.label,department:p.department||'全公司',time:new Date().toLocaleString('zh-TW',{hour12:false})});localStorage.setItem('bombhr-sensitive-audit-v121',JSON.stringify(rows.slice(0,200)))}
function auditPanel(){const rows=getAuditLog();return panel('敏感操作稽核紀錄','薪資匯出、關帳與完整銀行帳號查看均保留操作人及時間',`<div class="table-wrap"><table><thead><tr><th>操作</th><th>資料</th><th>操作人</th><th>角色</th><th>時間</th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td><b>${x.action}</b></td><td>${x.target}</td><td>${x.operator}・${x.operatorId}</td><td>${x.role}</td><td>${x.time}</td></tr>`).join(''):'<tr><td colspan="5">尚無敏感操作紀錄</td></tr>'}</tbody></table></div>`)}
function eventLogView(){const rows=getAuditLog();return head('事件紀錄','Event Log','集中查看敏感操作、權限異動與存取阻擋；顯示權限由最高權限設定')+panel('敏感操作與系統事件',`共 ${rows.length} 筆・保留實際操作人、員編、身份、責任部門與時間`,toolbar('搜尋操作、資料、姓名或員編')+`<div class="table-wrap"><table><thead><tr><th>事件</th><th>資料／責任範圍</th><th>實際操作人</th><th>身份</th><th>責任部門</th><th>時間</th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr data-search-row><td><b>${x.action}</b></td><td>${x.target}</td><td>${x.operator}・${x.operatorId}</td><td>${x.role}</td><td>${x.department||'—'}</td><td>${x.time}</td></tr>`).join(''):'<tr><td colspan="6" class="empty-state">尚無事件紀錄</td></tr>'}</tbody></table></div>`)}
views.eventlog=eventLogView;
const originalDashboardPage=views.dashboard;
views.dashboard=()=>{const pending=pendingApprovalCounts();return originalDashboardPage().replace('<strong>32</strong><small class="trend warn">7 件需要優先處理</small>',`<strong>${28+pending.total}</strong><small class="trend ${pending.total?'warn':'up'}">${pending.total?`${pending.total} 件簽核需要優先處理`:'簽核案件已全部完成'}</small>`)};
views.organization=()=>head('組織與職務管理','Organization','ABOMB 台中總公司・部門、職務與到離職資料管理',`<button class="secondary-btn" data-add="department">新增部門</button>`)+`<div class="org-grid">${panel('企業範圍','單一營運據點',`<div class="tree-node active"><b>ABOMB 台中總公司</b><span>1,248</span></div><div class="tree-node child"><span>人事部</span><span>26</span></div><div class="tree-node child"><span>財務部</span><span>38</span></div><div class="tree-node child"><span>營運部</span><span>1,184</span></div>`)}${panel('部門與職務','資料範圍：台中總公司',toolbar('搜尋部門或職務')+`<div class="table-wrap"><table><thead><tr><th>部門</th><th>主管</th><th>人數</th><th>職務管理</th><th>操作</th></tr></thead><tbody>${[['人事部','林怡君','26','8 個職務'],['財務部','李佳穎','38','6 個職務'],['營運管理部','陳冠宇','184','12 個職務'],['門市營運部','王志豪','1,000','18 個職務']].map(x=>`<tr><td><b>${x[0]}</b></td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td class="row-actions"><button data-generic-edit>編輯</button></td></tr>`).join('')}</tbody></table></div>`)}</div>`;
views.reports=()=>head('報表中心','Reports','ABOMB 台中總公司・人事與出勤營運報表',`<button class="secondary-btn" data-export>匯出報表清單</button>`)+`<div class="report-hub-grid">${[['◷','出勤報表','每日出勤、遲到、缺勤、未打卡與補卡結果','attendance'],['＋','加班報表','核准時數、加班費、補休與部門成本','overtime'],['◇','請假報表','假別、剩餘額度、請假趨勢與代理安排','leave'],['⌁','人力分析報表','在職、到離職、排班缺口與部門人力','workforce']].map(x=>`<button class="report-entry" data-report="${x[3]}"><i>${x[0]}</i><div><b>${x[1]}</b><small>${x[2]}</small></div><span>查看 →</span></button>`).join('')}</div>${panel('最近產製報表','僅顯示目前角色可存取的資料範圍',`<div class="table-wrap"><table><thead><tr><th>報表名稱</th><th>期間</th><th>範圍</th><th>產製人</th><th>操作</th></tr></thead><tbody><tr><td>7 月出勤彙總</td><td>2026/07</td><td>台中總公司</td><td>林怡君</td><td class="row-actions"><button data-export>下載</button></td></tr><tr><td>第二季人力分析</td><td>2026 Q2</td><td>台中總公司</td><td>陳冠宇</td><td class="row-actions"><button data-export>下載</button></td></tr></tbody></table></div>`)}`;
function simpleModule(t,en,d,label,value){return head(t,en,d,`<button class="secondary-btn" data-export>匯出報表</button><button class="primary-btn" data-generic-create>新增項目</button>`)+`<div class="stat-grid">${stat(label,value,'資料更新於今天 08:30')}${stat('待處理項目','12','較上週 -3','trend up')}${stat('本月完成','86','完成率 91%')}${stat('異常提醒','3','需要檢視','trend warn')}</div>${panel('近期項目','依更新時間排序',`<div class="alert-list"><div class="alert-item"><i>◇</i><div><b>${t}例行檢核</b><small>ABOMB 全公司・今天 09:20</small></div>${badge('進行中')}</div><div class="alert-item"><i>✓</i><div><b>上月資料封存</b><small>林怡君・昨天 16:40</small></div>${badge('已完成')}</div></div>`)}`}
function attendanceRecords(){const appRows=getSharedEvents().filter(e=>e.category==='attendance').map(e=>`<tr data-search-row><td>${e.employee}<small style="display:block;color:var(--muted)">${e.employeeId||''}・APP 即時</small></td><td>${e.action==='clock-in'?(e.time||'—'):'—'}</td><td>${e.action==='clock-out'?(e.time||'—'):'—'}</td><td>${e.method||'裝置＋GPS'}</td><td>${e.location||'ABOMB 台中總公司'}</td><td>${badge(e.status||'正常')}</td></tr>`).join('');return panel('今日打卡紀錄','裝置綁定＋位置啟用為預設',toolbar('搜尋員工或打卡方式',`<select class="filter-select"><option>全部狀態</option><option>正常</option><option>遲到</option><option>未打卡</option></select>`)+`<div class="table-wrap"><table><thead><tr><th>員工</th><th>上班</th><th>下班</th><th>打卡方式</th><th>位置／裝置</th><th>狀態</th></tr></thead><tbody>${appRows}${[['OG','08:27','—','GPS','iPhone 17 Pro・台中總公司','正常'],['KEN','08:35','—','Wi-Fi','台中總公司','正常'],['RU','08:43','—','GPS','台中總公司','遲到'],['肉肉','—','—','—','裝置定位未啟用','異常']].map(x=>`<tr data-search-row><td>${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td>${x[4]}</td><td>${badge(x[5])}</td></tr>`).join('')}</tbody></table></div>`) }
function deviceTab(){return panel('員工裝置綁定','一位員工原則綁定一個主要裝置',toolbar('搜尋姓名、員編或裝置')+`<div class="table-wrap"><table><thead><tr><th>員工</th><th>裝置</th><th>最後活動</th><th>狀態</th><th>操作</th></tr></thead><tbody>${employees.slice(0,4).map((e,i)=>`<tr data-search-row><td>${e[0]}<small style="display:block;color:var(--muted)">${e[1]}</small></td><td>${['iPhone 17 Pro','Pixel 11','iPhone 16','Samsung S26'][i]}</td><td>今天 08:${27+i*4}</td><td>${badge(i===3?'待重新綁定':'已綁定')}</td><td class="row-actions"><button data-device-reset>解除綁定</button></td></tr>`).join('')}</tbody></table></div>`)}
function methodsTab(){return panel('企業打卡方式','裝置綁定與位置啟用為必要條件',`<div class="settings-grid">${setting('裝置綁定＋位置','預設打卡方式',true,true)}${setting('指定 Wi-Fi','企業選用',true)}${setting('QR Code','企業選用',false)}${setting('Beacon 藍牙','企業選用',false)}${setting('NFC 感應','特殊場域選用',false)}</div>`)}
function setting(t,s,on,lock=false){return `<div class="setting-row"><div><b>${t}</b><small>${s}</small></div><label class="switch"><input type="checkbox" ${on?'checked':''} ${lock?'disabled':''}><span></span></label></div>`}
function settingsApp(){return panel('Employee App 功能開關','變更將套用至權限範圍內員工',`<div class="settings-grid">${setting('打卡與出勤紀錄','核心功能',true,true)}${setting('班表與營運月曆','顯示個人班表',true)}${setting('請假／加班／補卡','員工自助申請',true)}${setting('薪資表','可由企業控制顯示',false)}${setting('教育訓練','課程與學習紀錄',true)}${setting('AI 助理','目前預設關閉',false)}</div>`)}
function leaveSettings(){return panel('企業自訂假別','法定假別不可停用；福利假可自由啟用',`<div class="settings-grid">${setting('特別休假／年假','法定假別',true,true)}${setting('事假／病假','法定假別',true,true)}${setting('旅遊假','企業福利假',true)}${setting('生日假','企業福利假',true)}${setting('公司福利假','企業自訂',false)}${setting('代理人允許選擇「無」','申請時可不填代理人',true)}</div>`)}
