function basicSettings(){return panel('企業基本設定','ABOMB',`<div class="form-grid"><label class="form-field">企業顯示名稱<input class="form-control" value="ABOMB"></label><label class="form-field">預設語言<select class="form-control"><option>繁體中文</option><option>English</option></select></label><label class="form-field">主要時區<select class="form-control"><option>Asia/Taipei (UTC+8)</option></select></label><label class="form-field">員工編號政策<select class="form-control"><option>離職後不可重複使用</option></select></label></div>`)}
const scheduleToday=new Date(),scheduleStart=new Date(2025,10,1),scheduleEnd=new Date(2027,11,1);let scheduleCursor=new Date(Math.min(2027,Math.max(2025,scheduleToday.getFullYear())),scheduleToday.getFullYear()<2025?10:scheduleToday.getFullYear()>2027?11:scheduleToday.getMonth(),1),scheduleMode='month';
function monthKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function scheduleMonths(){const count=(scheduleEnd.getFullYear()-scheduleStart.getFullYear())*12+scheduleEnd.getMonth()-scheduleStart.getMonth()+1;return Array.from({length:count},(_,i)=>new Date(scheduleStart.getFullYear(),scheduleStart.getMonth()+i,1))}
function scheduleMonthOptions(){return scheduleMonths().map(d=>`<option value="${monthKey(d)}" ${monthKey(d)===monthKey(scheduleCursor)?'selected':''}>${d.getFullYear()} 年 ${d.getMonth()+1} 月</option>`).join('')}
function lunarLabel(date){try{return new Intl.DateTimeFormat('zh-TW-u-ca-chinese',{month:'short',day:'numeric'}).format(date).replace(/\s/g,'')}catch(e){return ''}}
function approvedLeaveEvents(){return getSharedEvents().filter(e=>e.category==='approval'&&e.subtype==='leave'&&e.status==='approved')}
function scheduleCalendarDays(){const y=scheduleCursor.getFullYear(),m=scheduleCursor.getMonth(),first=new Date(y,m,1).getDay(),gridStart=new Date(y,m,1-first),leaves=approvedLeaveEvents();return Array.from({length:42},(_,i)=>{const date=new Date(gridStart.getFullYear(),gridStart.getMonth(),gridStart.getDate()+i),day=date.getDate(),muted=date.getMonth()!==m,isToday=date.getFullYear()===scheduleToday.getFullYear()&&date.getMonth()===scheduleToday.getMonth()&&day===scheduleToday.getDate(),dateKey=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,items=leaves.filter(e=>{const [s,z]=String(e.period||'').split('–');return s&&z&&dateKey>=s&&dateKey<=z});return `<div class="day ${muted?'muted':''} ${isToday?'today':''}" data-day="${day}" data-date="${dateKey}"><div class="day-head"><b>${day}</b><span class="lunar">${lunarLabel(date)}</span></div>${items.map(e=>`<span class="shift warn">${e.employee}・${e.leaveType||e.title}</span>`).join('')}</div>`}).join('')}
function weekSchedule(){return `<div class="empty-state">目前沒有已建立的班別；核准的請假會自動顯示在月曆。</div>`}
function staffSchedule(){return `<div class="table-wrap"><table><thead><tr><th>員工</th><th>本月排班</th><th>預定工時</th><th>已核准休假</th><th>操作</th></tr></thead><tbody><tr><td colspan="5" class="empty-state">尚未建立任何排班資料</td></tr></tbody></table></div>`}
function schedulingView(){if(!window.BOMBHR_SCHEDULING)return `<div class="scheduling-core-loading"><div><i></i><b>正在載入新版排班</b><span>請稍候，班表核心載入完成後會自動顯示</span></div></div>`;const historical=scheduleCursor<new Date(scheduleToday.getFullYear(),scheduleToday.getMonth(),1),atStart=monthKey(scheduleCursor)===monthKey(scheduleStart),atEnd=monthKey(scheduleCursor)===monthKey(scheduleEnd),body=scheduleMode==='month'?`<div class="calendar-scroll"><div class="calendar-head"><span>一</span><span>二</span><span>三</span><span>四</span><span>五</span><span>六</span><span>日</span></div><div class="calendar-grid">${scheduleCalendarDays()}</div></div>`:scheduleMode==='week'?weekSchedule():staffSchedule();return head('班表','Scheduling','2025/11～2027/12 快速檢視、農曆、主管備註與跨據點人力支援',`<button class="secondary-btn" data-copy-month ${historical?'disabled':''}>複製上月班表</button><button class="secondary-btn" data-calendar-note ${historical?'disabled':''}>新增主管備註</button><button class="primary-btn" data-add="shift" ${historical?'disabled':''}>新增班別</button>`)+`<div class="schedule-toolbar"><div class="month-nav"><button class="icon-btn" data-schedule-prev ${atStart?'disabled':''}>‹</button><select id="scheduleMonthSelect">${scheduleMonthOptions()}</select><button class="icon-btn" data-schedule-next ${atEnd?'disabled':''}>›</button><button class="secondary-btn" data-schedule-today>回到今天</button></div><div class="schedule-view-switch"><button data-schedule-view="month" class="${scheduleMode==='month'?'active':''}">月</button><button data-schedule-view="week" class="${scheduleMode==='week'?'active':''}">週</button><button data-schedule-view="staff" class="${scheduleMode==='staff'?'active':''}">人員</button></div></div>${historical?'<div class="history-banner">歷史班表為唯讀模式；所有原始班別與異動紀錄永久保留。</div>':''}`+panel(`${scheduleCursor.getFullYear()} 年 ${scheduleCursor.getMonth()+1} 月`,`${historical?'歷史唯讀':'可編輯'}・ABOMB 全公司・可選範圍 2025/11～2027/12`,body)}
function refreshScheduling(){location.hash='scheduling';window.dispatchEvent(new HashChangeEvent('hashchange'))}
function bindScheduling(){const shift=delta=>{const d=new Date(scheduleCursor.getFullYear(),scheduleCursor.getMonth()+delta,1);if(d>=scheduleStart&&d<=scheduleEnd){scheduleCursor=d;refreshScheduling()}};$('[data-schedule-prev]')?.addEventListener('click',()=>shift(-1));$('[data-schedule-next]')?.addEventListener('click',()=>shift(1));$('#scheduleMonthSelect')?.addEventListener('change',e=>{const [y,m]=e.target.value.split('-').map(Number);scheduleCursor=new Date(y,m-1,1);refreshScheduling()});$('[data-schedule-today]')?.addEventListener('click',()=>{scheduleCursor=new Date(scheduleToday.getFullYear(),scheduleToday.getMonth(),1);refreshScheduling()});$$('[data-schedule-view]').forEach(b=>b.onclick=()=>{scheduleMode=b.dataset.scheduleView;refreshScheduling()});$('[data-copy-month]')?.addEventListener('click',()=>openModal('複製上月班表',`複製至 ${scheduleCursor.getFullYear()} 年 ${scheduleCursor.getMonth()+1} 月`,`<div class="detail-box"><small>來源月份</small><b>${new Date(scheduleCursor.getFullYear(),scheduleCursor.getMonth()-1,1).getFullYear()} 年 ${new Date(scheduleCursor.getFullYear(),scheduleCursor.getMonth()-1,1).getMonth()+1} 月</b></div><p style="color:var(--muted)">將複製班別、人員配置與主管備註；請假及臨時異常不會被複製。</p>`,`<button class="secondary-btn" data-modal-close>取消</button><button class="primary-btn" id="copyScheduleConfirm">確認複製</button>`));setTimeout(()=>{if($('#copyScheduleConfirm'))$('#copyScheduleConfirm').onclick=()=>{closeModal();toast('上月班表已複製，尚未發布')}},0);$$('[data-staff-schedule]').forEach(b=>b.onclick=()=>toast(`已開啟 ${b.dataset.staffSchedule} 的個人班表`))}
