function formFields(type){const sets={employee:[['姓名','例如：陳小華'],['員工編號','由系統依規則產生'],['公司／據點','ABOMB・台北總部'],['部門','選擇部門'],['職位','可自行輸入'],['任用狀態','試用期 3 個月']],location:[['據點名稱','例如：新竹據點'],['據點代碼','例如：HSZ01'],['地址','完整地址'],['負責主管','選擇主管']],department:[['部門名稱','例如：品牌行銷部'],['部門代碼','例如：MKT'],['上層組織','ABOMB'],['部門主管','選擇主管']],role:[['群組名稱','企業自訂名稱'],['資料範圍','全公司／據點／部門'],['說明','權限群組用途']],shift:[['班別名稱','例如：門市早班'],['上班時間','08:30'],['下班時間','17:30'],['休息分鐘','60']],device:[['員工姓名／員編','搜尋員工'],['裝置識別碼','自動取得或輸入']],announcement:[['公告標題','輸入標題'],['發布範圍','全公司'],['重要程度','一般']],note:[['日期','2026/07/27'],['主管備註','例如：月末盤點']],generic:[['項目名稱','輸入名稱'],['資料範圍','ABOMB 全公司']]};return sets[type]||sets.generic}
function openForm(type){if(type==='employee'){employeeOnboardingModal();enhanceEmployeePhotoFields();enhanceEmployeeBankFields();populateEnterpriseBankSelect();return}if(type==='role'){openModal('新增權限群組','企業可自訂名稱、功能與資料範圍；不得仿冒或覆蓋受保護的經營管理最高權限',`<div class="form-grid"><label class="form-field">群組名稱<input id="newRoleName" class="form-control" placeholder="例如：區域營運管理"></label><label class="form-field">資料範圍<select id="newRoleScope" class="form-control"><option>ABOMB 台中總公司</option><option>所屬部門</option><option>本人資料</option></select></label><label class="form-field full">功能權限<input id="newRoleFeatures" class="form-control" placeholder="例如：人事查看／排班編輯／報表查看"></label></div><p id="newRoleError" class="form-error"></p>`,`<button class="secondary-btn" data-modal-close>取消</button><button class="primary-btn" id="modalSave">建立群組</button>`);$('#modalSave').onclick=()=>{const name=$('#newRoleName').value.trim(),features=$('#newRoleFeatures').value.trim();if(!name||!features){$('#newRoleError').textContent='請填寫群組名稱與功能權限。';return}if(/經營管理|老闆|副理|經理/.test(name)){ $('#newRoleError').textContent='經營管理為受保護的最高權限範本，不可另建或仿冒。';return}const rows=getPermissionGroups();rows.push({name,members:'0',features,scope:$('#newRoleScope').value,protected:false});localStorage.setItem('bombhr-permission-groups-v121',JSON.stringify(rows));closeModal();window.dispatchEvent(new HashChangeEvent('hashchange'));toast('自訂權限群組已建立')};return}const names={location:'新增據點',department:'新增部門',shift:'新增班別',device:'綁定員工裝置',announcement:'發布公告',note:'新增主管備註',generic:'編輯項目'};const list=formFields(type);const fields=list.map((f,i)=>`<label class="form-field ${i===list.length-1&&list.length%2?'full':''}">${f[0]}<input class="form-control" placeholder="${f[1]}"></label>`).join('');openModal(names[type]||'新增項目','Demo 表單・儲存後會顯示操作結果',`<div class="form-grid">${fields}</div>`,`<button class="secondary-btn" data-modal-close>取消</button><button class="primary-btn" id="modalSave">儲存</button>`);$('#modalSave').onclick=()=>{closeModal();toast(`${names[type]||'項目'}已儲存`)} }
function employeeModal(id,edit){const e=getEmployeeRecord(id);if(!e)return;const salary=e.salary||getSalaryStructures().find(s=>s.position===e.position),leave=e.leaveEntitlement||getBenefitLeaves().find(x=>x.level===e.benefitLevel);const editable=edit&&['executive','hradmin','supervisor'].includes(currentRole());openModal(edit?'編輯員工資料':'員工人事主檔',`${e.name}・${e.employeeId}`,`<div class="employee-profile-banner"><div class="avatar">${e.name[0]}</div><div><b>${e.name}</b><small>${e.position}・${e.department}</small></div>${badge(e.status)}</div><div class="detail-grid"><div class="detail-box"><small>姓名（不可由本人修改）</small><b>${e.name}</b></div><div class="detail-box"><small>員工編號（不可重複使用）</small><b>${e.employeeId}</b></div><div class="detail-box"><small>出生年月日</small><b>${e.birthDate||'—'}</b></div><div class="detail-box"><small>公司／據點</small><b>${e.company||'ABOMB'}・${e.location}</b></div><div class="detail-box"><small>部門／職位</small><b>${e.department}・${e.position}</b></div><div class="detail-box"><small>到職日／任用</small><b>${e.hireDate||'—'}・${e.employmentType||e.status}</b></div><div class="detail-box"><small>直屬主管</small><b>${e.manager||'—'}</b></div><div class="detail-box"><small>公司 Email</small><b>${e.email||'—'}</b></div><div class="detail-box"><small>權限群組／帳號</small><b>${e.roleGroup||'一般員工'}・${e.accountStatus||'啟用'}</b></div></div>${salary?`<div class="employee-linked-data"><div><small>套用薪資架構</small><b>${salary.position}・NT$ ${salaryFixedTotal(salary).toLocaleString()}</b></div><div><small>福利假別</small><b>${e.benefitLevel||'員工'}・旅遊假 ${leave?.travel||0} 天・年假 ${leave?.annual||0} 天</b></div></div>`:''}${editable?`<div class="form-grid edit-employee-fields"><label class="form-field">工作據點<select id="editEmployeeLocation" class="form-control"><option>台中總公司</option></select></label><label class="form-field">部門<input id="editEmployeeDepartment" class="form-control" value="${e.department||''}"></label><label class="form-field">職位<input id="editEmployeePosition" class="form-control" value="${e.position||''}"></label><label class="form-field">直屬主管<input id="editEmployeeManager" class="form-control" value="${e.manager||''}"></label><label class="form-field">帳號／任職狀態<select id="editEmployeeStatus" class="form-control"><option ${e.status==='試用期'?'selected':''}>試用期</option><option ${e.status==='在職'?'selected':''}>在職</option><option ${e.status==='培訓中'?'selected':''}>培訓中</option><option>停用</option></select></label></div>`:edit?'<div class="policy-note">此為預載 Demo 員工；完整編輯功能適用於新建立員工資料。</div>':''}`,edit?`<button class="secondary-btn" data-modal-close>取消</button><button class="primary-btn" id="modalSave">儲存變更</button>`:'');if(edit)$('#modalSave').onclick=()=>{if(editable){const changes={location:$('#editEmployeeLocation').value,department:$('#editEmployeeDepartment').value.trim(),position:$('#editEmployeePosition').value.trim(),manager:$('#editEmployeeManager').value.trim(),status:$('#editEmployeeStatus').value,updatedBy:`${currentProfile().name}・${currentProfile().id}`,updatedAt:new Date().toISOString()},list=getCustomEmployees(),record=list.find(x=>x.employeeId===id);if(record){Object.assign(record,changes);localStorage.setItem('bombhr-custom-employees',JSON.stringify(list))}else{let overrides={};try{overrides=JSON.parse(localStorage.getItem('bombhr-employee-org-overrides')||'{}')}catch(e){}overrides[id]={...(overrides[id]||{}),...changes};localStorage.setItem('bombhr-employee-org-overrides',JSON.stringify(overrides))}addAudit('調整員工組織資料',`${e.name}・部門 ${changes.department}・職位 ${changes.position}・主管 ${changes.manager}`)}closeModal();location.hash='employees';window.dispatchEvent(new HashChangeEvent('hashchange'));toast('員工資料已更新並留下異動紀錄')}}
const specialistSalaryTemplate={base:30300,positionAllowance:19504,attendanceBonus:3000,seniorityAllowance:2000,overtime:0,laborPensionIncome:1196,healthInsurance:0,laborInsurance:0,lateDeduction:0,pensionContribution:0,effectiveDate:'2026-07-01',benefitLevel:'員工',travelLeave:7,annualLeave:7};
function getEmployeeSalaryProfiles(){try{return JSON.parse(localStorage.getItem('bombhr-employee-salary-profiles')||'{}')}catch(e){return {}}}
function closestInsuranceGrade(grades,salary){return grades.find(amount=>amount>=Number(salary||0))||grades[grades.length-1]}
function employeeSalaryProfile(id){const saved=getEmployeeSalaryProfiles()[id];if(saved)return {...specialistSalaryTemplate,...saved};const base=Number(getEmployeeRecord(id)?.salary?.base||specialistSalaryTemplate.base);return {...specialistSalaryTemplate,base,laborGrade:closestInsuranceGrade(laborInsuranceGrades,base),healthGrade:closestInsuranceGrade(healthInsuranceGrades,base)}}
function canEditEmployeeSalary(){return ['executive','hradmin'].includes(currentRole())}
function insuranceGradeOptions(grades,selected){return grades.map((amount,i)=>`<option value="${amount}" ${Number(selected)===amount?'selected':''}>第 ${i+1} 級・NT$ ${amount.toLocaleString()}</option>`).join('')}
function enhanceEmployeeSalaryPage(id){const e=getEmployeeRecord(id);if(!e||!$('#modalBody'))return;const original=$('#modalBody').innerHTML,p=employeeSalaryProfile(id),canEdit=canEditEmployeeSalary(),disabled=canEdit?'':'disabled',annualUsed=window.BOMBHR_HR_LEDGER?.summary(id).find(x=>x.rule.id==='annual')?.used||0;$('#modalBody').innerHTML=`<div class="employee-record-tabs"><button class="active" data-employee-page="basic">第 1 頁｜基本人事資料</button><button data-employee-page="salary">第 2 頁｜薪資架構與員工福利</button></div><div data-employee-panel="basic">${original}</div><div data-employee-panel="salary" hidden><div class="salary-access-note ${canEdit?'editable':'readonly'}"><b>${canEdit?'目前權限可調整員工固定薪資':'目前權限僅可查看員工薪資'}</b><small>${canEdit?'儲存時必須填寫生效日，系統會保留修改人與時間。':'只有經營管理與財務人事行政可以修改。'}</small></div><div class="employee-salary-page"><section><div class="section-heading"><div><b>專員薪資架構</b><small>以最初設定的專員項目作為此員工基本薪資架構</small></div><strong id="employeeSalaryTotal">NT$ ${(p.base+p.positionAllowance+p.attendanceBonus+p.seniorityAllowance+p.laborPensionIncome).toLocaleString()}</strong></div><div class="salary-field-grid">${[['base','底薪',p.base],['positionAllowance','職務津貼',p.positionAllowance],['attendanceBonus','全勤獎金',p.attendanceBonus],['seniorityAllowance','年資津貼',p.seniorityAllowance],['overtime','加班費（每月變動）',p.overtime],['laborPensionIncome','勞退（原表收入欄）',p.laborPensionIncome]].map(x=>`<label>${x[1]}<input data-employee-salary="${x[0]}" type="number" value="${x[2]}" ${disabled}></label>`).join('')}</div></section><section><div class="section-heading"><div><b>扣款與雇主提撥</b><small>扣款在薪資及薪資條中一律以負號顯示</small></div></div><div class="salary-field-grid">${[['healthInsurance','全民健保',p.healthInsurance],['laborInsurance','勞保費',p.laborInsurance],['lateDeduction','遲到扣款',p.lateDeduction],['pensionContribution','勞退提撥金（雇主）',p.pensionContribution]].map(x=>`<label>${x[1]}<input data-employee-salary="${x[0]}" type="number" value="${x[2]}" ${disabled}></label>`).join('')}</div></section><section><div class="section-heading"><div><b>員工福利與假別</b><small>手動調整後會同步班表假勤、Employee App 與年度薪資結算</small></div></div><div class="salary-field-grid"><label>福利資格<select id="employeeBenefitLevel" ${disabled}><option ${p.benefitLevel==='新進員工'?'selected':''}>新進員工</option><option ${p.benefitLevel==='員工'?'selected':''}>員工</option><option ${p.benefitLevel==='主管'?'selected':''}>主管</option><option ${p.benefitLevel==='經理'?'selected':''}>經理</option></select></label><label>旅遊假<input id="employeeTravelLeave" type="number" value="${p.travelLeave}" ${disabled}></label><label>本年度核發年假<input id="employeeAnnualLeave" type="number" min="0" step=".5" value="${p.annualLeave}" ${disabled}></label><label>已使用年假<input id="employeeAnnualUsed" type="number" min="0" step=".5" value="${annualUsed}" ${disabled}></label><label>調整生效日<input id="employeeSalaryEffective" type="date" value="${p.effectiveDate}" ${disabled}></label><label class="full">年假調整原因<input id="employeeAnnualReason" value="依人員任用／調動狀況調整" ${disabled}></label></div><div class="policy-note">剩餘年假＝本年度核發－已使用。核准請假會自動增加已使用；人事手動修改則會留下調整前後、原因、操作人與時間。</div></section>${canEdit?'<div class="salary-page-actions"><button class="primary-btn" id="saveEmployeeSalaryProfile">儲存薪資與福利設定</button></div>':''}</div></div>`;$$('[data-employee-page]').forEach(b=>b.onclick=()=>{$$('[data-employee-page]').forEach(x=>x.classList.toggle('active',x===b));$$('[data-employee-panel]').forEach(x=>x.hidden=x.dataset.employeePanel!==b.dataset.employeePage)});const updateTotal=()=>{const v=n=>Number($(`[data-employee-salary="${n}"]`)?.value||0);$('#employeeSalaryTotal').textContent=`NT$ ${(v('base')+v('positionAllowance')+v('attendanceBonus')+v('seniorityAllowance')+v('laborPensionIncome')).toLocaleString()}`};$$('[data-employee-salary]').forEach(x=>x.oninput=updateTotal);if(canEdit)$('#saveEmployeeSalaryProfile').onclick=()=>{}}
function approvalModal(i){const a=approvals[i],d=approvalDetails[i],att=d.attachment;const attachment=att?`<div class="attachment-card"><img src="${att.url==='assets/demo-medical-receipt.svg'?att.url:'../assets/bombhr-logo.png'}" alt="附件縮圖"><div><b>${att.name}</b><small>${att.size}</small></div><div class="attachment-actions">${att.url!=='#'?`<a href="${att.url}" target="_blank" rel="noopener">預覽</a><a href="${att.url}" download>下載</a>`:'<a href="#" data-demo-file>預覽</a>'}</div></div>`:`<div class="no-attachment">未附附件・此申請類型附件非必填</div>`;openModal('審核申請',`${a[1]}・${a[2]}`,`<div class="approval-summary"><div class="detail-box"><small>日期／時段</small><b>${a[3]}</b></div><div class="detail-box"><small>申請天數／時數</small><b>${d.duration}</b></div><div class="detail-box"><small>可用額度／累計</small><b>${d.balance}</b></div><div class="detail-box"><small>代理人／主管確認</small><b>${d.agent}</b></div><div class="detail-box"><small>送出時間</small><b>${d.submitted}</b></div><div class="detail-box"><small>審核狀態</small><b>${a[5]}</b></div></div><div class="approval-reason"><small>申請原因</small><p>${d.reason}</p></div><div class="attachment-section"><div class="attachment-title"><b>證明文件與附件</b><small>${att?'1 個附件':'0 個附件'}</small></div>${attachment}</div><label class="form-field" style="margin-top:15px">審核備註<textarea class="form-control" rows="3" placeholder="選填；退回時建議填寫原因"></textarea></label>`,`<button class="danger-btn" id="rejectBtn">退回</button><button class="primary-btn" id="approveBtn">核准</button>`);$('#rejectBtn').onclick=()=>{closeModal();toast('申請已退回並通知申請人')};$('#approveBtn').onclick=()=>{closeModal();toast('申請已核准並同步 Employee App')};$('[data-demo-file]')?.addEventListener('click',e=>{e.preventDefault();toast('Demo：已開啟旅遊行程附件預覽')})}
function sharedApprovalModal(id){const e=getSharedEvents().find(x=>x.id===id||x.eventId===id);if(!e)return;const files=e.attachments?.length?e.attachments.map(f=>`<div class="attachment-card"><div class="file-icon">↗</div><div><b>${f.name}</b><small>${f.size||'Employee App 上傳附件'}</small></div><div class="attachment-actions"><button data-app-file>預覽</button></div></div>`).join(''):'<div class="no-attachment">未附附件・此申請類型附件非必填</div>';openModal('Employee App 即時申請',`${e.title}・${e.employee}（${e.employeeId}）`,`<div class="approval-summary"><div class="detail-box"><small>申請期間</small><b>${e.period||'—'}</b></div><div class="detail-box"><small>天數／時數</small><b>${e.duration||'—'}</b></div><div class="detail-box"><small>代理人</small><b>${e.agent||'無'}</b></div><div class="detail-box"><small>送出時間</small><b>${e.submitted||'剛剛'}</b></div></div><div class="approval-reason"><small>申請原因</small><p>${e.reason||'未填寫'}</p></div><div class="attachment-section"><div class="attachment-title"><b>證明文件與附件</b><small>${e.attachments?.length||0} 個附件</small></div>${files}</div><label class="form-field" style="margin-top:15px">審核備註<textarea id="sharedReviewNote" class="form-control" rows="3" placeholder="退回時請填寫原因"></textarea></label>`,`<button class="danger-btn" id="sharedReject">退回</button><button class="primary-btn" id="sharedApprove">核准</button>`);$$('[data-app-file]').forEach(b=>b.onclick=()=>toast('Demo 已讀取 Employee App 上傳的附件資訊'));$('#sharedReject').onclick=()=>{const note=$('#sharedReviewNote').value.trim()||'申請資料需補充，請修改後重新送出。';updateSharedApproval(id,'rejected','已退回',note);closeModal();toast('已退回，結果同步至 Employee App')};$('#sharedApprove').onclick=()=>{updateSharedApproval(id,'approved','已核准');closeModal();toast('已核准，結果同步至 Employee App')}}
function payrollManualModal(){openModal('手動新增薪資項目','單筆建立固定薪、津貼、獎金或扣款',`<div class="form-grid"><label class="form-field">員工<select class="form-control"><option>林怡君・AB00001</option><option>王小明・AB00128</option></select></label><label class="form-field">薪資項目<select class="form-control"><option>本薪</option><option>職務津貼</option><option>績效獎金</option><option>其他扣款</option></select></label><label class="form-field">金額<input class="form-control" type="number" value="3000"></label><label class="form-field">生效月份<input class="form-control" type="month" value="2026-07"></label><label class="form-field full">備註<textarea class="form-control" rows="3" placeholder="輸入異動原因"></textarea></label></div>`,`<button class="secondary-btn" data-modal-close>取消</button><button class="primary-btn" id="savePayrollItem">儲存薪資項目</button>`);$('#savePayrollItem').onclick=()=>{closeModal();toast('薪資項目已建立並留下異動紀錄')}}
function payrollImportModal(){openModal('匯入薪資與福利檔案','支援 Excel（.xlsx／.xls）與 CSV，匯入前先預覽欄位',`<a class="template-download" href="assets/templates/bombhr-payroll-import-template.xlsx" download><span>↓</span><div><b>下載 BOMB HR 薪資匯入範例</b><small>含填寫說明、範例資料、下拉選項與必填驗證</small></div><strong>下載 .xlsx</strong></a><div class="import-guide"><b>1. 下載並填寫範例</b><span>→</span><b>2. 上傳與欄位預覽</b><span>→</span><b>3. 驗證後匯入</b></div><label class="upload-zone">拖曳填寫完成的檔案至此，或點擊選擇<input id="payrollFile" type="file" accept=".xlsx,.xls,.csv"></label><div id="importPreview" class="import-preview"><small>尚未選擇檔案</small></div>`,`<button class="secondary-btn" data-modal-close>取消</button><button class="primary-btn" id="confirmImport" disabled>開始匯入</button>`);$('#payrollFile').onchange=e=>{const f=e.target.files[0];if(!f)return;$('#importPreview').innerHTML=`<b>${f.name}</b><small>${Math.ceil(f.size/1024)} KB・已通過格式檢查</small><div class="mini-import-table">偵測欄位：員工編號｜薪資月份｜薪資項目｜金額｜生效日</div>`;$('#confirmImport').disabled=false};$('#confirmImport').onclick=()=>{closeModal();toast('檔案驗證完成，Demo 已匯入 24 筆資料')}}
function benefitManageModal(){const benefits=getBenefits(),leaves=getBenefitLeaves();openModal('2026 年度員工福利主檔','依最新 Word 文件建立；HR 可直接修改金額、規則、假別天數與啟用狀態',`<div class="benefit-editor-wrap"><table class="benefit-editor"><thead><tr><th>啟用</th><th>分類</th><th>福利名稱／關係</th><th>金額</th><th>發放與申請規則</th></tr></thead><tbody>${benefits.map((b,i)=>`<tr data-benefit-row="${i}"><td><input data-benefit-field="enabled" type="checkbox" ${b.enabled?'checked':''}></td><td><select data-benefit-field="category"><option ${b.category==='節慶／生活'?'selected':''}>節慶／生活</option><option ${b.category==='婚喪喜慶'?'selected':''}>婚喪喜慶</option><option ${b.category==='喪葬補助'?'selected':''}>喪葬補助</option></select></td><td><input data-benefit-field="name" value="${b.name}"></td><td><input data-benefit-field="amount" type="number" value="${b.amount}"></td><td><input data-benefit-field="rule" value="${b.rule}"></td></tr>`).join('')}</tbody></table></div><h4 class="benefit-subtitle">假別資格與年度天數</h4><div class="leave-entitlement-grid">${leaves.map((l,i)=>`<div data-leave-row="${i}"><b>${l.level}</b><label>旅遊假<input data-leave-field="travel" type="number" min="0" value="${l.travel}"> 天</label><label>年假<input data-leave-field="annual" type="number" min="0" value="${l.annual}"> 天</label></div>`).join('')}</div><div class="policy-note">新進員工轉為正式員工或升任主管／經理後，系統會依生效日重新計算可用假別；歷史額度與申請紀錄不會被覆蓋。</div>`,`<button class="secondary-btn" data-modal-close>取消</button><button class="primary-btn" id="saveBenefit">儲存福利與假別</button>`);$('#saveBenefit').onclick=()=>{const nextBenefits=$$('[data-benefit-row]').map(row=>{const get=f=>row.querySelector(`[data-benefit-field="${f}"]`);return {enabled:get('enabled').checked,category:get('category').value,name:get('name').value,amount:Number(get('amount').value||0),rule:get('rule').value}}),nextLeaves=$$('[data-leave-row]').map((row,i)=>({level:leaves[i].level,travel:Number(row.querySelector('[data-leave-field="travel"]').value||0),annual:Number(row.querySelector('[data-leave-field="annual"]').value||0)}));localStorage.setItem('bombhr-benefit-policies',JSON.stringify(nextBenefits));localStorage.setItem('bombhr-benefit-leaves',JSON.stringify(nextLeaves));closeModal();location.hash='payroll';window.dispatchEvent(new HashChangeEvent('hashchange'));toast('2026 年度福利與假別規則已儲存')}}
function confirmModal(t,msg,ok,onConfirm){openModal(t,'此操作會留下稽核紀錄',`<p>${msg}</p>`,`<button class="secondary-btn" data-modal-close>取消</button><button class="danger-btn" id="confirmBtn">${ok}</button>`);$('#confirmBtn').onclick=()=>{if(onConfirm)onConfirm();closeModal();toast('操作已完成並記錄操作人與時間')}}
function setupScope(){const data=[['TC','ABOMB 台中總公司','1,248 位員工']];const pop=$('#scopePopover');$('#scopeLabel').textContent='ABOMB 台中總公司';$('.scope-mini b').textContent='ABOMB 台中總公司';function draw(q=''){$('#scopeList').innerHTML=data.filter(x=>x.join('').includes(q)).map(x=>`<button class="scope-option active" data-scope="${x[1]}"><span>${x[0]}</span><div><b>${x[1]}</b><small>${x[2]}</small></div></button>`).join('')}draw();$('#scopeBtn').onclick=e=>{const r=e.currentTarget.getBoundingClientRect();pop.style.top=r.bottom+8+'px';pop.style.left=Math.max(10,r.left)+'px';pop.classList.toggle('open')};$('#scopeSearch').oninput=e=>draw(e.target.value)}
function updateNotificationIndicators(){const c=pendingApprovalCounts(),count=2+c.total,badgeEl=$('#notificationBtn em'),tab=$('[data-drawer-tab="notify"] span');if(badgeEl){badgeEl.textContent=count;badgeEl.hidden=count===0}if(tab)tab.textContent=count}
function removeResolvedApprovalNotices(){const done=new Set(getAdminApprovalRecords().map(r=>r.id));if(done.has('DEMO-0'))$$('#drawerBody .notice-item').filter(x=>x.textContent.includes('王思涵提交')).forEach(x=>x.remove())}
function setupNotifications(){const drawer=$('#notificationDrawer'),mask=$('#drawerMask');updateNotificationIndicators();const open=()=>{drawer.classList.add('open');mask.classList.add('open');drawDrawer('notify');removeResolvedApprovalNotices()},close=()=>{drawer.classList.remove('open');mask.classList.remove('open')};$('#notificationBtn').onclick=open;mask.onclick=close;$('[data-close-drawer]').onclick=close;$$('[data-drawer-tab]').forEach(b=>b.onclick=()=>{$$('[data-drawer-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');drawDrawer(b.dataset.drawerTab);removeResolvedApprovalNotices()});$('#soundSwitch').onchange=e=>toast(e.target.checked?'重要事件音效已開啟':'重要事件音效已關閉')}
const demoTasks=[{id:'attendance-check',route:'attendance',title:'完成今日出勤異常核對'},{id:'leave-review',route:'approvals',title:'審核 12 件請假申請'},{id:'support-list',route:'scheduling',title:'確認台中跨店支援名單'}];
function getCompletedTasks(){try{return JSON.parse(localStorage.getItem('bombhr-completed-tasks')||'[]')}catch(e){return []}}
function taskDrawerHtml(){const completed=getCompletedTasks(),pending=demoTasks.filter(t=>!completed.some(c=>c.id===t.id)),done=completed.filter(c=>demoTasks.some(t=>t.id===c.id));return `<div class="task-section-head"><b>待確認</b><small>${pending.length} 件</small></div><div class="task-list">${pending.length?pending.map(t=>`<div class="task-item task-confirm-row" data-task-id="${t.id}"><label><input type="checkbox"><span>${t.title}</span></label><button class="task-confirm-btn" data-confirm-task="${t.id}" disabled>確認完成</button><button class="task-route-btn" data-task-route="${t.route}" aria-label="前往處理">→</button></div>`).join(''):'<div class="task-empty">目前沒有待確認事項</div>'}</div>${pending.length?`<div class="task-bulk-bar"><label><input id="selectAllTasks" type="checkbox"> 全選</label><button id="confirmSelectedTasks" class="primary-btn" disabled>確認選取項目已完成</button></div>`:''}<details class="completed-tasks" ${done.length?'':'hidden'}><summary>已完成紀錄（${done.length}）</summary>${done.map(c=>`<div class="completed-task"><span>✓</span><div><b>${c.title}</b><small>${c.reviewer}・${c.completedAt}</small></div></div>`).join('')}</details>`}
function drawDrawer(type){const body=$('#drawerBody');body.innerHTML=type==='notify'?`<div class="notice-list"><div class="notice-item" data-quick-route="scheduling"><i>!</i><div><b>台中據點臨時人力缺口</b><small>2 分鐘前・需要跨店支援</small></div></div><div class="notice-item" data-quick-route="approvals"><i>✓</i><div><b>王思涵提交事假申請</b><small>12 分鐘前・等待審核</small></div></div><div class="notice-item" data-quick-route="attendance"><i>◷</i><div><b>5 位員工裝置定位異常</b><small>25 分鐘前・重大異常</small></div></div></div>`:taskDrawerHtml();$$('[data-quick-route]',body).forEach(item=>item.onclick=()=>{location.hash=item.dataset.quickRoute;$('#notificationDrawer').classList.remove('open');$('#drawerMask').classList.remove('open');toast('已開啟對應處理頁面')});const refreshBulk=()=>{const inputs=$$('[data-task-id] input',body),selected=inputs.filter(x=>x.checked);if($('#confirmSelectedTasks'))$('#confirmSelectedTasks').disabled=!selected.length;if($('#selectAllTasks'))$('#selectAllTasks').checked=inputs.length>0&&selected.length===inputs.length};$$('[data-task-id] input',body).forEach(input=>input.onchange=()=>{const row=input.closest('[data-task-id]'),button=row.querySelector('[data-confirm-task]');row.classList.toggle('ready',input.checked);button.disabled=!input.checked;refreshBulk()});$('#selectAllTasks')?.addEventListener('change',e=>{$$('[data-task-id] input',body).forEach(input=>{input.checked=e.target.checked;input.dispatchEvent(new Event('change'))})});$('#confirmSelectedTasks')?.addEventListener('click',()=>confirmTasks($$('[data-task-id] input:checked',body).map(x=>x.closest('[data-task-id]').dataset.taskId)));$$('[data-task-route]',body).forEach(button=>button.onclick=()=>{location.hash=button.dataset.taskRoute;$('#notificationDrawer').classList.remove('open');$('#drawerMask').classList.remove('open');toast('已開啟待辦處理頁面')});$$('[data-confirm-task]',body).forEach(button=>button.onclick=()=>confirmTask(button.dataset.confirmTask))}
function confirmTask(id){const task=demoTasks.find(t=>t.id===id);if(!task)return;openModal('確認完成待辦',task.title,`<div class="detail-box"><small>完成者</small><b>林怡君・AB00001・HR 系統管理者</b></div><p style="color:var(--muted)">確認後會移出待辦清單，並保留完成時間與登入身分紀錄。</p>`,`<button class="secondary-btn" data-modal-close>取消</button><button class="primary-btn" id="completeTaskBtn">確認已完成</button>`);$('#completeTaskBtn').onclick=()=>{const completed=getCompletedTasks();if(!completed.some(c=>c.id===id))completed.unshift({...task,reviewer:'林怡君（AB00001）',completedAt:new Date().toLocaleString('zh-TW',{hour12:false})});localStorage.setItem('bombhr-completed-tasks',JSON.stringify(completed));closeModal();drawDrawer('task');toast('待辦已確認完成，紀錄已保留')}}
function confirmTasks(ids){if(!ids.length)return;openModal('批次確認完成',`共選取 ${ids.length} 件待辦`,`<div class="detail-box"><small>確認人</small><b>林怡君・AB00001・HR 系統管理者</b></div><p style="color:var(--muted)">確認後，選取項目會移至已完成紀錄並保留時間戳記。</p>`,`<button class="secondary-btn" data-modal-close>取消</button><button class="primary-btn" id="completeSelectedTasks">確認全部完成</button>`);$('#completeSelectedTasks').onclick=()=>{const completed=getCompletedTasks(),time=new Date().toLocaleString('zh-TW',{hour12:false});ids.forEach(id=>{const task=demoTasks.find(t=>t.id===id);if(task&&!completed.some(c=>c.id===id))completed.unshift({...task,reviewer:'林怡君（AB00001）',completedAt:time})});localStorage.setItem('bombhr-completed-tasks',JSON.stringify(completed));closeModal();drawDrawer('task');toast(`已確認完成 ${ids.length} 件待辦`)}}
function setupSearch(){const cmd=$('#command'),input=$('#globalSearch');window.openSearch=()=>{cmd.classList.add('open');input.focus();search('')};$('#searchBtn').onclick=openSearch;cmd.onclick=e=>{if(e.target===cmd)cmd.classList.remove('open')};input.oninput=e=>search(e.target.value);function search(q){const items=[['營運總覽','dashboard'],['員工人事主檔','employees'],['林怡君 AB00001','employees'],['出勤與裝置管理','attendance'],['簽核中心','approvals'],['角色與權限群組','permissions'],['企業系統設定','settings']].filter(x=>x[0].includes(q));$('#searchResults').innerHTML=items.map(x=>`<button class="search-result" data-search-route="${x[1]}"><span>${x[0]}</span><small>開啟 →</small></button>`).join('');$$('[data-search-route]').forEach(b=>b.onclick=()=>{location.hash=b.dataset.searchRoute;cmd.classList.remove('open')})}}
function setupProfile(){const pop=$('#profilePopover'),profile=currentProfile();$('#profileBtn').onclick=e=>{const r=e.currentTarget.getBoundingClientRect();pop.style.top=r.bottom+8+'px';pop.style.right='14px';pop.classList.toggle('open')};$$('[data-profile]').forEach(b=>b.onclick=()=>{pop.classList.remove('open');openModal(b.dataset.profile==='account'?'我的帳號':'權限資料範圍',`${profile.name}・${profile.id}`,b.dataset.profile==='account'?`<div class="detail-grid"><div class="detail-box"><small>角色</small><b>${profile.label}</b></div><div class="detail-box"><small>登入方式</small><b>員工編號</b></div></div>`:`<div class="detail-box"><small>目前範圍</small><b>ABOMB 台中總公司・依角色功能權限</b></div>`)})}
document.addEventListener('change',e=>{if(e.target.id!=='selectAllTasks')return;const checked=e.target.checked;setTimeout(()=>{const body=$('#drawerBody');$$('[data-task-id] input',body).forEach(input=>{input.checked=checked;const row=input.closest('[data-task-id]');row.classList.toggle('ready',checked);row.querySelector('[data-confirm-task]').disabled=!checked});const bulk=$('#confirmSelectedTasks');if(bulk)bulk.disabled=!checked},0)},true);
function enhanceEmployeeBankFields(){const preview=$('#salaryAutoPreview');if(!preview)return;preview.insertAdjacentHTML('beforebegin',`<div class="employee-form-section bank-section"><b>薪資轉帳銀行資料</b><div class="form-grid"><label class="form-field">銀行名稱 *<select id="newEmployeeBank" class="form-control"><option value="">請選擇銀行</option><option>國泰世華銀行</option><option>中國信託銀行</option><option>台新銀行</option><option>玉山銀行</option><option>第一銀行</option><option>其他銀行</option></select></label><label class="form-field">分行名稱 *<input id="newEmployeeBankBranch" class="form-control" placeholder="例如：台北分行"></label><label class="form-field">銀行戶名 *<input id="newEmployeeAccountName" class="form-control" placeholder="須與員工本人姓名相符"></label><label class="form-field">銀行帳號 *<input id="newEmployeeBankAccount" class="form-control" inputmode="numeric" autocomplete="off" placeholder="請輸入完整帳號"></label></div><label class="bankbook-upload">上傳存摺封面或銀行帳戶證明照片 *<small>JPG、PNG、WEBP；Demo 上限 1.2 MB</small><input id="newEmployeeBankbook" type="file" accept="image/jpeg,image/png,image/webp"></label><div id="bankbookPreview" class="bankbook-preview"><small>尚未選擇銀行帳戶照片</small></div></div>`);let bankbookData='',bankbookName='';$('#newEmployeeBankbook').onchange=e=>{const file=e.target.files[0];if(!file)return;if(file.size>1258291){$('#employeeFormError').textContent='銀行帳戶照片超過 1.2 MB，請壓縮後重新上傳。';e.target.value='';return}const reader=new FileReader();reader.onload=()=>{bankbookData=reader.result;bankbookName=file.name;$('#bankbookPreview').innerHTML=`<img src="${bankbookData}" alt="銀行帳戶照片預覽"><div><b>${file.name}</b><small>${Math.ceil(file.size/1024)} KB・已準備儲存</small></div>`};reader.readAsDataURL(file)};const button=$('#saveNewEmployee'),original=button.onclick;button.onclick=()=>{if(currentRole()==='supervisor'){original();return}const bank=$('#newEmployeeBank').value,branch=$('#newEmployeeBankBranch').value.trim(),accountName=$('#newEmployeeAccountName').value.trim(),account=$('#newEmployeeBankAccount').value.replace(/\s/g,'');if(!bank||!branch||!accountName||!account||!bankbookData){$('#employeeFormError').textContent='請完整填寫銀行、分行、戶名、帳號並上傳銀行帳戶照片。';return}if(!/^\d{8,20}$/.test(account)){$('#employeeFormError').textContent='銀行帳號應為 8–20 位數字，請重新確認。';return}const before=getCustomEmployees().length;original();const list=getCustomEmployees();if(list.length===before+1){const record=list[list.length-1];record.bank={bank,branch,accountName,account,bankbookName,bankbookData,verified:false,updatedAt:new Date().toISOString()};localStorage.setItem('bombhr-custom-employees',JSON.stringify(list))}}}
function enhanceEmployeeBankDetails(id){const e=getEmployeeRecord(id);if(!e?.bank||!$('#modalBody'))return;const account=e.bank.account||'',masked=account.length>5?`${account.slice(0,3)}•••••${account.slice(-3)}`:'••••••••';$('#modalBody').insertAdjacentHTML('beforeend',`<div class="bank-detail-card"><div><small>薪資轉帳銀行</small><b>${e.bank.bank}・${e.bank.branch}</b></div><div><small>戶名</small><b>${e.bank.accountName}</b></div><div><small>帳號（預設遮罩）</small><b id="maskedBankAccount">${masked}</b></div><button class="secondary-btn" data-reveal-bank="${account}">顯示完整帳號</button>${e.bank.bankbookData?`<a href="${e.bank.bankbookData}" target="_blank" rel="noopener"><img src="${e.bank.bankbookData}" alt="存摺或銀行帳戶證明"><span>查看銀行帳戶照片</span></a>`:''}</div>`);$('[data-reveal-bank]')?.addEventListener('click',event=>{const b=event.currentTarget;if(b.dataset.visible){$('#maskedBankAccount').textContent=masked;b.textContent='顯示完整帳號';delete b.dataset.visible}else{addAudit('查看完整銀行帳號',`${e.name}・${e.employeeId}`);$('#maskedBankAccount').textContent=b.dataset.revealBank;b.textContent='隱藏完整帳號';b.dataset.visible='1';toast('已記錄查看人與時間')}})}
document.addEventListener('click',e=>{const view=e.target.closest('[data-view-employee],[data-edit-employee]');if(view)setTimeout(()=>enhanceEmployeeBankDetails(view.dataset.viewEmployee||view.dataset.editEmployee),0)},true);
function populateEnterpriseBankSelect(){const select=$('#newEmployeeBank');if(!select)return;select.innerHTML='<option value="">請選擇企業銀行</option>'+getEnterpriseBanks().filter(x=>x.active).map(x=>`<option value="${x.name}" data-branch="${x.branch}">${x.code}・${x.name}（${x.branch}）</option>`).join('');select.onchange=()=>{const option=select.selectedOptions[0];if(option?.dataset.branch)$('#newEmployeeBankBranch').value=option.dataset.branch}}
function enterpriseBankModal(){const draw=()=>{const banks=getEnterpriseBanks();openModal('企業銀行主檔','新增公司可使用的薪轉與付款銀行；員工建檔時直接選用',`<div class="bank-master-list">${banks.map((b,i)=>`<div class="bank-master-row"><span>${b.code}</span><div><b>${b.name}</b><small>${b.branch}・${b.purpose}</small></div>${badge(b.active?'啟用':'停用')}<button data-remove-bank="${i}">移除</button></div>`).join('')}</div><div class="bank-add-form"><b>新增銀行</b><div class="form-grid"><label class="form-field">銀行代碼 *<input id="bankMasterCode" class="form-control" maxlength="3" placeholder="例如：004"></label><label class="form-field">銀行名稱 *<input id="bankMasterName" class="form-control" placeholder="例如：臺灣銀行"></label><label class="form-field">分行名稱 *<input id="bankMasterBranch" class="form-control" placeholder="例如：台北分行"></label><label class="form-field">用途<select id="bankMasterPurpose" class="form-control"><option>員工薪資轉帳</option><option>企業付款</option><option>備用薪轉銀行</option></select></label></div><p id="bankMasterError" class="form-error"></p></div>`,`<button class="secondary-btn" data-modal-close>關閉</button><button class="primary-btn" id="addEnterpriseBank">新增銀行</button>`);$$('[data-remove-bank]').forEach(b=>b.onclick=()=>{const next=getEnterpriseBanks();next.splice(+b.dataset.removeBank,1);saveEnterpriseBanks(next);draw();toast('銀行已從企業主檔移除')});$('#addEnterpriseBank').onclick=()=>{const code=$('#bankMasterCode').value.trim(),name=$('#bankMasterName').value.trim(),branch=$('#bankMasterBranch').value.trim(),purpose=$('#bankMasterPurpose').value;if(!/^\d{3}$/.test(code)||!name||!branch){$('#bankMasterError').textContent='請填寫3位銀行代碼、銀行名稱與分行。';return}const next=getEnterpriseBanks();if(next.some(x=>x.code===code&&x.branch===branch)){$('#bankMasterError').textContent='相同銀行代碼與分行已存在。';return}next.push({code,name,branch,purpose,active:true});saveEnterpriseBanks(next);draw();toast(`${name}已新增至企業銀行主檔`)}};draw()}
function enhanceEmployeePhotoFields(){const section=$('.employee-form-section');if(!section)return;section.querySelector('b').insertAdjacentHTML('afterend',`<div class="employee-photo-upload"><div id="employeePhotoPreview" class="employee-photo-preview">照</div><label>上傳員工大頭照<small>後台與 Employee App 共用同一張照片</small><input id="newEmployeePhoto" type="file" accept="image/jpeg,image/png,image/webp"></label></div>`);let photoData='',photoName='';$('#newEmployeePhoto').onchange=e=>{const file=e.target.files[0];if(!file)return;if(file.size>1258291){$('#employeeFormError').textContent='大頭照超過 1.2 MB，請壓縮後重新上傳。';return}const reader=new FileReader();reader.onload=()=>{photoData=reader.result;photoName=file.name;$('#employeePhotoPreview').innerHTML=`<img src="${photoData}" alt="員工大頭照預覽">`};reader.readAsDataURL(file)};const button=$('#saveNewEmployee'),original=button.onclick;button.onclick=()=>{const id=$('#newEmployeeId').value,before=getCustomEmployees().length;original();if(photoData&&getCustomEmployees().length===before+1){const list=getCustomEmployees(),record=list[list.length-1];record.profilePhoto={name:photoName,data:photoData,updatedAt:new Date().toISOString(),source:'Enterprise HR Admin'};localStorage.setItem('bombhr-custom-employees',JSON.stringify(list));const photos=getProfilePhotos();photos[id]=photoData;localStorage.setItem('bombhr-employee-profile-photos',JSON.stringify(photos));window.dispatchEvent(new CustomEvent('bombhr-profile-photo-update',{detail:{employeeId:id}}))}}}
