function enhanceSalaryGradeReference(){if(!$('.payroll-item-wrap')||$('#insuranceGradeToggle'))return;$('.payroll-item-summary')?.insertAdjacentHTML('beforeend','<button class="secondary-btn" id="insuranceGradeToggle">查看投保級距表</button>');$('.payroll-item-wrap')?.insertAdjacentHTML('afterend',`<section class="insurance-grade-reference" id="insuranceGradeReference" hidden><div class="grade-head"><div><b>115 年投保級距對照表</b><small>2026/01/01 起適用・資料來源：勞保局、健保署</small></div><div class="grade-tabs"><button class="active" data-grade-tab="labor">勞保</button><button data-grade-tab="health">健保</button><button data-grade-close>收合</button></div></div><div class="grade-scroll"><table><thead><tr><th>等級</th><th>月投保金額</th><th>實際薪資月額</th></tr></thead><tbody id="gradeTableBody">${gradeRows(laborInsuranceGrades)}</tbody></table></div><div class="grade-source-links"><a href="https://www.bli.gov.tw/0005475.html" target="_blank" rel="noopener">勞保局官方分級表 ↗</a><a href="https://www.nhi.gov.tw/ch/cp-19421-f9533-2569-1.html" target="_blank" rel="noopener">健保署官方分級表 ↗</a><span>法規更新時由系統管理者更新版本，不直接鎖死在薪資公式。</span></div></section>`);$('#insuranceGradeToggle').onclick=()=>{$('#insuranceGradeReference').hidden=false;$('#insuranceGradeReference').scrollIntoView({behavior:'smooth',block:'nearest'})};$('[data-grade-close]').onclick=()=>$('#insuranceGradeReference').hidden=true;$$('[data-grade-tab]').forEach(b=>b.onclick=()=>{$$('[data-grade-tab]').forEach(x=>x.classList.toggle('active',x===b));$('#gradeTableBody').innerHTML=gradeRows(b.dataset.gradeTab==='health'?healthInsuranceGrades:laborInsuranceGrades)})}
