// V1.40 notification lifecycle, audible alerts and explicit close controls.
const notificationReadKeyV140='bombhr-read-notifications-v140';
function notificationItemsV140(){return [{id:'staff-gap-20260721',route:'scheduling',icon:'!',title:'台中據點臨時人力缺口',detail:'需要跨店支援'},{id:'location-alert-20260721',route:'attendance',icon:'◷',title:'5 位員工裝置定位異常',detail:'重大異常'}]}
function readNotificationIdsV140(){try{return JSON.parse(localStorage.getItem(notificationReadKeyV140)||'[]')}catch(e){return []}}
function unreadStaticCountV140(){const read=new Set(readNotificationIdsV140());return notificationItemsV140().filter(item=>!read.has(item.id)).length}
function markNotificationsReadV140(){localStorage.setItem(notificationReadKeyV140,JSON.stringify([...new Set([...readNotificationIdsV140(),...notificationItemsV140().map(item=>item.id)])]));updateNotificationIndicators()}
function updateNotificationIndicators(){const approvals=pendingApprovalCounts().total,notices=unreadStaticCountV140()+approvals,completed=getCompletedTasks(),tasks=demoTasks.filter(task=>!completed.some(done=>done.id===task.id)).length,badgeEl=$('#notificationBtn em'),notifyTab=$('[data-drawer-tab="notify"] span'),taskTab=$('[data-drawer-tab="task"] span');if(badgeEl){badgeEl.textContent=notices;badgeEl.hidden=notices===0}if(notifyTab)notifyTab.textContent=notices;if(taskTab)taskTab.textContent=tasks}
let notificationAudioContextV140=null;
function notificationSoundEnabledV140(){return localStorage.getItem('bombhr-notification-sound')!=='off'}
function playNotificationSoundV140(showMessage=false){if(!notificationSoundEnabledV140()){if(showMessage)toast('請先開啟重要事件音效');return false}try{notificationAudioContextV140=notificationAudioContextV140||new(window.AudioContext||window.webkitAudioContext)();const ctx=notificationAudioContextV140;ctx.resume();const now=ctx.currentTime;[0,.18].forEach((delay,index)=>{const oscillator=ctx.createOscillator(),gain=ctx.createGain();oscillator.type='sine';oscillator.frequency.setValueAtTime(index?880:660,now+delay);gain.gain.setValueAtTime(.0001,now+delay);gain.gain.exponentialRampToValueAtTime(.16,now+delay+.02);gain.gain.exponentialRampToValueAtTime(.0001,now+delay+.16);oscillator.connect(gain).connect(ctx.destination);oscillator.start(now+delay);oscillator.stop(now+delay+.18)});if(showMessage)toast('通知音效播放正常');return true}catch(error){if(showMessage)toast('瀏覽器尚未允許播放音效，請再點一次測試');return false}}
function setupNotifications(){const drawer=$('#notificationDrawer'),mask=$('#drawerMask'),soundSwitch=$('#soundSwitch');soundSwitch.checked=notificationSoundEnabledV140();updateNotificationIndicators();const open=()=>{drawer.classList.add('open');mask.classList.add('open');drawDrawer('notify');markNotificationsReadV140()},close=()=>{drawer.classList.remove('open');mask.classList.remove('open')};$('#notificationBtn').onclick=open;mask.onclick=close;$('[data-close-drawer]').onclick=close;$$('[data-drawer-tab]').forEach(button=>button.onclick=()=>{$$('[data-drawer-tab]').forEach(item=>item.classList.remove('active'));button.classList.add('active');drawDrawer(button.dataset.drawerTab);if(button.dataset.drawerTab==='notify')markNotificationsReadV140()});soundSwitch.onchange=event=>{localStorage.setItem('bombhr-notification-sound',event.target.checked?'on':'off');if(event.target.checked)playNotificationSoundV140();toast(event.target.checked?'重要事件音效已開啟':'重要事件音效已關閉')};$('#soundTestBtn').onclick=()=>playNotificationSoundV140(true);document.addEventListener('pointerdown',()=>{if(notificationSoundEnabledV140()&&!notificationAudioContextV140){try{notificationAudioContextV140=new(window.AudioContext||window.webkitAudioContext)()}catch(error){}}},{once:true});window.addEventListener('storage',event=>{if(event.key==='bombhr-demo-events'){playNotificationSoundV140();updateNotificationIndicators()}})}
function drawDrawer(type){const body=$('#drawerBody'),pending=pendingApprovalCounts().total,approvalItem=pending?`<div class="notice-item" data-quick-route="approvals"><i>✓</i><div><b>${pending} 件簽核事件等待處理</b><small>處理完成後會自動移除通知與紅點</small></div></div>`:'';body.innerHTML=type==='notify'?`<div class="notice-list">${notificationItemsV140().map(item=>`<div class="notice-item" data-quick-route="${item.route}"><i>${item.icon}</i><div><b>${item.title}</b><small>${item.detail}</small></div></div>`).join('')}${approvalItem}</div>`:taskDrawerHtml();$$('[data-quick-route]',body).forEach(item=>item.onclick=()=>{location.hash=item.dataset.quickRoute;$('#notificationDrawer').classList.remove('open');$('#drawerMask').classList.remove('open');toast('已開啟對應處理頁面')});const refreshBulk=()=>{const inputs=$$('[data-task-id] input',body),selected=inputs.filter(x=>x.checked);if($('#confirmSelectedTasks'))$('#confirmSelectedTasks').disabled=!selected.length;if($('#selectAllTasks'))$('#selectAllTasks').checked=inputs.length>0&&selected.length===inputs.length};$$('[data-task-id] input',body).forEach(input=>input.onchange=()=>{const row=input.closest('[data-task-id]'),button=row.querySelector('[data-confirm-task]');row.classList.toggle('ready',input.checked);button.disabled=!input.checked;refreshBulk()});$('#selectAllTasks')?.addEventListener('change',event=>{$$('[data-task-id] input',body).forEach(input=>{input.checked=event.target.checked;input.dispatchEvent(new Event('change'))})});$('#confirmSelectedTasks')?.addEventListener('click',()=>confirmTasks($$('[data-task-id] input:checked',body).map(input=>input.closest('[data-task-id]').dataset.taskId)));$$('[data-task-route]',body).forEach(button=>button.onclick=()=>{location.hash=button.dataset.taskRoute;$('#notificationDrawer').classList.remove('open');$('#drawerMask').classList.remove('open');toast('已開啟待辦處理頁面')});$$('[data-confirm-task]',body).forEach(button=>button.onclick=()=>confirmTask(button.dataset.confirmTask))}
function globalClick(event){if(event.target.matches('[data-modal-close]'))closeModal();if(event.target.matches('[data-command-close]'))$('#command')?.classList.remove('open');const popClose=event.target.closest('[data-close-popover]');if(popClose)$('#'+popClose.dataset.closePopover)?.classList.remove('open');if(event.target.matches('#detailAction')){closeModal();toast('已開啟完整明細視圖')}if(event.target.matches('#dayAction')){closeModal();openForm('note')}if(event.target.matches('#copyScheduleConfirm')){closeModal();toast('上月班表已複製，尚未發布')}if(event.target.matches('#saveSupervisorAttendance')){closeModal();toast('出勤紀錄已儲存，並記錄主管身份與填寫時間')}}
function setupSearch(){const command=$('#command'),input=$('#globalSearch');window.openSearch=()=>{command.classList.add('open');input.focus();search('')};$('#searchBtn').onclick=openSearch;input.oninput=event=>search(event.target.value);function search(query){const items=[['營運總覽','dashboard'],['員工人事主檔','employees'],['林怡君 AB00001','employees'],['出勤與裝置管理','attendance'],['簽核中心','approvals'],['角色與權限群組','permissions'],['企業系統設定','settings']].filter(item=>item[0].includes(query));$('#searchResults').innerHTML=items.map(item=>`<button class="search-result" data-search-route="${item[1]}"><span>${item[0]}</span><small>開啟 →</small></button>`).join('');$$('[data-search-route]').forEach(button=>button.onclick=()=>{location.hash=button.dataset.searchRoute;command.classList.remove('open')})}}
