const enhanceEmployeeSalaryPageV124=enhanceEmployeeSalaryPage;
enhanceEmployeeSalaryPage=function(id){enhanceEmployeeSalaryPageV124(id);const p=employeeSalaryProfile(id),canEdit=canEditEmployeeSalary(),disabled=canEdit?'':'disabled',sections=$$('.employee-salary-page>section');if(sections.length<2)return;sections[1].insertAdjacentHTML('afterend',`<section class="insurance-grade-section"><div class="section-heading"><div><b>勞保／健保投保級距</b><small>115 年級距；與員工人事資料、薪資扣款及投保資料連動</small></div><button class="secondary-btn" id="showEmployeeGradeTable">查看完整級距表</button></div><div class="salary-field-grid"><label>勞保投保級距<select id="employeeLaborGrade" ${disabled}>${insuranceGradeOptions(laborInsuranceGrades,p.laborGrade)}</select></label><label>健保投保級距<select id="employeeHealthGrade" ${disabled}>${insuranceGradeOptions(healthInsuranceGrades,p.healthGrade)}</select></label><label>級距生效日<input type="date" value="${p.effectiveDate}" disabled></label></div><div id="employeeGradeTable" class="employee-grade-table" hidden><div class="grade-tabs"><button class="active" data-employee-grade="labor">勞保級距</button><button data-employee-grade="health">健保級距</button></div><div class="grade-scroll"><table><thead><tr><th>等級</th><th>月投保金額</th><th>實際薪資月額</th></tr></thead><tbody id="employeeGradeRows">${gradeRows(laborInsuranceGrades)}</tbody></table></div></div></section>`);$('#showEmployeeGradeTable').onclick=()=>{$('#employeeGradeTable').hidden=!$('#employeeGradeTable').hidden};$$('[data-employee-grade]').forEach(b=>b.onclick=()=>{$$('[data-employee-grade]').forEach(x=>x.classList.toggle('active',x===b));$('#employeeGradeRows').innerHTML=gradeRows(b.dataset.employeeGrade==='health'?healthInsuranceGrades:laborInsuranceGrades)});if(canEdit&&$('#saveEmployeeSalaryProfile')){const originalSave=$('#saveEmployeeSalaryProfile').onclick;$('#saveEmployeeSalaryProfile').onclick=()=>{originalSave();const all=getEmployeeSalaryProfiles();if(all[id]){all[id].laborGrade=Number($('#employeeLaborGrade').value);all[id].healthGrade=Number($('#employeeHealthGrade').value);localStorage.setItem('bombhr-employee-salary-profiles-v124',JSON.stringify(all))}}}};
